#include <bits/stdc++.h>
using namespace std;

constexpr int INF = 10000000;
constexpr int MAX_C = 8;

int n, m, c, rewardCount;
int rewardIndex[10];
char mp[25][25];
bool blocked[25][25];
int val[10], px[10], py[10], sx, sy;
int dx[4] = {1, 0, -1, 0};
int dy[4] = {0, -1, 0, 1};
int dp[25][25][1 << MAX_C];
int sum[1 << MAX_C];

struct State {
    int x, y, mask;
};

bool cross(int x1, int y1, int x2, int y2, int id) {
    if (x1 != x2 || x1 >= px[id]) return false;
    return min(y1, y2) < py[id] && py[id] <= max(y1, y2);
}

void bfs() {
    memset(dp, -1, sizeof(dp));

    queue<State> q;
    dp[sx][sy][0] = 0;
    q.push({sx, sy, 0});

    while (!q.empty()) {
        State now = q.front();
        q.pop();

        for (int i = 0; i < 4; ++i) {
            int nx = now.x + dx[i];
            int ny = now.y + dy[i];

            if (nx <= 0 || nx > n || ny <= 0 || ny > m || blocked[nx][ny])
                continue;

            int nextMask = now.mask;
            for (int j = 0; j < c; ++j) {
                if (cross(now.x, now.y, nx, ny, j))
                    nextMask ^= 1 << j;
            }

            if (dp[nx][ny][nextMask] == -1) {
                dp[nx][ny][nextMask] = dp[now.x][now.y][now.mask] + 1;
                q.push({nx, ny, nextMask});
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m;

    for (int i = 1; i <= n; ++i)
        cin >> (mp[i] + 1);

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            if (mp[i][j] == '#') {
                blocked[i][j] = true;
            } else if (mp[i][j] == 'S') {
                sx = i;
                sy = j;
            } else if (isdigit(static_cast<unsigned char>(mp[i][j]))) {
                rewardIndex[rewardCount++] = c;
                px[c] = i;
                py[c] = j;
                ++c;
            } else if (mp[i][j] == 'B') {
                val[c] = -INF;
                px[c] = i;
                py[c] = j;
                ++c;
            }
        }
    }

    for (int i = 0; i < rewardCount; ++i)
        cin >> val[rewardIndex[i]];

    for (int mask = 1; mask < (1 << c); ++mask) {
        for (int j = 0; j < c; ++j) {
            if (mask & (1 << j))
                sum[mask] += val[j];
        }
    }

    bfs();

    int ans = 0;
    for (int mask = 0; mask < (1 << c); ++mask) {
        if (dp[sx][sy][mask] != -1)
            ans = max(ans, sum[mask]);
    }

    cout << ans;
    return 0;
}

